  detectedLanguageLabel: ["{detected} detected · file says {declared}", "本文: {detected} · ファイル名: {declared}", "본문: {detected} · 파일명: {declared}", "正文：{detected} · 文件名：{declared}", "Texto: {detected} · archivo: {declared}"],
  languageConflictWarning: ["The filename and text indicate different languages. Please verify this entry.", "ファイル名と本文の言語が一致しません。この項目を確認してください。", "파일명과 본문의 언어가 다릅니다. 이 항목을 확인하세요.", "文件名和正文所示语言不一致，请检查此条目。", "El nombre del archivo y el texto indican idiomas distintos. Revisa esta entrada."],
  ambiguousLanguageLabel: ["Text language unclear · file says {declared}", "本文言語を判定不能 · ファイル名: {declared}", "본문 언어 판정 불가 · 파일명: {declared}", "无法确定正文语言 · 文件名：{declared}", "Idioma del texto incierto · archivo: {declared}"],
  ambiguousLanguageWarning: ["The writing system does not identify one language safely. Enter or confirm the translation manually.", "文字体系だけでは言語を安全に特定できません。翻訳を手動で入力または確認してください。", "문자 체계만으로는 언어를 안전하게 특정할 수 없습니다. 번역을 직접 입력하거나 확인하세요.", "仅凭文字体系无法可靠确定语言，请手动输入或确认翻译。", "El sistema de escritura no permite identificar un idioma con seguridad. Introduce o confirma la traducción manualmente."],
