  downloadTranslationBundle: ["Download translation bundle", "翻訳バンドルをダウンロード", "번역 번들 다운로드", "下载翻译包", "Descargar paquete de traducción"],
  downloadTranslatedMod: ["Download translated mod", "翻訳済みMODをダウンロード", "번역된 MOD 다운로드", "下载翻译后的 MOD", "Descargar mod traducido"],
  downloadTranslationMod: ["Download translation mod", "翻訳MODをダウンロード", "번역 MOD 다운로드", "下载翻译 MOD", "Descargar mod de traducción"],
