const localeIndex = new Map([
  ["en", 0],
  ["ja", 1],
  ["ko", 2],
  ["zh-Hans", 3],
  ["es", 4],
]);

export function detectUiLocale(language = globalThis.navigator?.language) {
  const normalized = String(language || "").toLowerCase();
  if (normalized.startsWith("zh")) return "zh-Hans";
  const locale = UI_LOCALES.find((item) => normalized.startsWith(item.id.toLowerCase()));
  return locale?.id || "en";
}

export function createI18n(locale = detectUiLocale()) {
  const resolvedLocale = localeIndex.has(locale) ? locale : "en";
  const index = localeIndex.get(resolvedLocale);
  const t = (key, values = {}) => {
    const row = rows[key];
    let value = row?.[index] || row?.[0] || key;
    for (const [name, replacement] of Object.entries(values)) {
      value = value.replaceAll(`{${name}}`, String(replacement));
    }
    return value;
  };
  return {
    locale: resolvedLocale,
    numberLocale: resolvedLocale === "zh-Hans" ? "zh-CN" : resolvedLocale,
    t,
  };
}
